sn_aia_tool.script:
(function(inputs) {
// only string inputs are allowed 
// return outputs object where the keys in it are understandable by LLM
var upgradeList = [];
var getUpgrades = new GlideRecord('sys_upgrade_history');
getUpgrades.addQuery("upgrade_finished","!=","");
getUpgrades.addQuery("to_version","DOES NOT CONTAIN","Applied Update Set");
getUpgrades.addQuery("to_version","DOES NOT CONTAIN","com.glide.rollback");
getUpgrades.orderByDesc("sys_created_on");
getUpgrades.setLimit(3);
getUpgrades.query();
while(getUpgrades.next())
{
    upgradeList.push(
        {
            "upgraded_to":getUpgrades.to_version.toString(),
            "upgraded_from": getUpgrades.from_version.toString(),
            "skipped_upgrades":getUpgrades.changes_skipped,
            "upgrade_sys_id": getUpgrades.sys_id.toString()
        });
}
return JSON.stringify(upgradeList);
})(inputs);
